lace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) end ) end/case when sum(case when cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) is null then cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.mrp\'),\'\"\',\'\'),\',\',\'\') as float64) else cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) end )over (partition by cast(o.order_id as int64)) = 0 then 1 else sum(case when cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) is null then cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.mrp\'),\'\"\',\'\'),\',\',\'\') as float64) else cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) end )over (partition by cast(o.order_id as int64)) end ),0)) as discount , case when fo.order_id = o.order_id then \'New\' else \'Repeat\' end as new_customer_flag, case when date_trunc(cast(left(fo.order_date,10) as date),month) = date_trunc(cast(left(o.order_date,10) as date),month) then \'New\' else \'Repeat\' end as new_customer_flag_month, o.company_name as Warehouse_Name, cast(case when o.shipping_STATUS in (\'In Transit\', \'Shipment Created\') then date_diff(current_date(),date(left(o.ORDER_Date,10)),day) when o.shipping_STATUS in (\'Delivered\',\'Delivered To Origin\') then date_diff(date(left(o.shipping_Last_update_date,10)),date(left(o.ORDER_Date,10)),day) end as int64) as Days_in_Shipment, o.marketplace as Channel, o.payment_mode, o.import_date, o.last_update_date, o.pickup_pin_code pickup_pincode, row_number() over (partition by replace(JSON_EXTRACT_SCALAR(A,\'$.suborder_id\'),\'\"\',\'\') order by o.last_update_date desc) rw from orders o left join first_order fo on fo.contact_num = o.contact_num left join UNNEST(o.suborders) A ) s left join pick_up_dates pd on pd.Suborder_id = s.suborder_id left join intransit_dates id on id.Suborder_id = s.subo